PROGRAM p_cnt_2_fan
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
END_VAR
VAR
    Count : INT;
    PrevPulse : BOOL;
END_VAR
VAR CONSTANT
    CAP : INT := 2;
END_VAR

IF Reset THEN
    Count := 0;
